window.ScripturaLexicons.LSJ.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2656\" data-lsj-orig-id=\"n2656\" data-lsj-ordinal=\"2701\"><td class=\"greek\">αἴρινος</td><td>LSJ</td><td>De joio, relativo à planta daninha.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2657\" data-lsj-orig-id=\"n2657\" data-lsj-ordinal=\"2702\"><td class=\"greek\">αἰρολογέω</td><td>LSJ</td><td>Limpar de joio, retirar plantas daninhas.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2658\" data-lsj-orig-id=\"n2658\" data-lsj-ordinal=\"2703\"><td class=\"greek\">αἰρόπινον</td><td>LSJ</td><td>Peneira para separar o joio do trigo.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2659\" data-lsj-orig-id=\"n2659\" data-lsj-ordinal=\"2704\"><td class=\"greek\">ἄϊρος</td><td>LSJ</td><td>Iro infeliz, expressão homérica.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2660\" data-lsj-orig-id=\"n2660\" data-lsj-ordinal=\"2705\"><td class=\"greek\">αἴρω</td><td>LSJ</td><td>Remissão a ἀείρω, erguer.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2661\" data-lsj-orig-id=\"n2661\" data-lsj-ordinal=\"2706\"><td class=\"greek\">αἰρώδης</td><td>LSJ</td><td>Sujeito à infestação por joio.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2662\" data-lsj-orig-id=\"n2662\" data-lsj-ordinal=\"2707\"><td class=\"greek\">Αἶσα</td><td>LSJ</td><td>Aisa, divindade que distribui a sorte; destino, decreto, porção destinada, medida apropriada.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2663\" data-lsj-orig-id=\"n2663\" data-lsj-ordinal=\"2708\"><td class=\"greek\">αἴσακος</td><td>LSJ</td><td>Ramo de murta ou loureiro passado entre convivas como desafio para cantar.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2664\" data-lsj-orig-id=\"n2664\" data-lsj-ordinal=\"2709\"><td class=\"greek\">αἰσάλων</td><td>LSJ</td><td>Pequeno falcão, possivelmente esmerilhão (Falco aesalon).</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2665\" data-lsj-orig-id=\"n2665\" data-lsj-ordinal=\"2710\"><td class=\"greek\">αἰσθάνομαι</td><td>LSJ</td><td>Perceber pelos sentidos, sentir, ver, ouvir; compreender, tomar conhecimento.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2666\" data-lsj-orig-id=\"n2666\" data-lsj-ordinal=\"2711\"><td class=\"greek\">αἴσθημα</td><td>LSJ</td><td>Objeto da sensação; percepção sensorial.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2667\" data-lsj-orig-id=\"n2667\" data-lsj-ordinal=\"2712\"><td class=\"greek\">αἰσθησίη</td><td>LSJ</td><td>Equivalente a αἴσθησις, sensação.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2668\" data-lsj-orig-id=\"n2668\" data-lsj-ordinal=\"2713\"><td class=\"greek\">αἴσθησις</td><td>LSJ</td><td>Sensação, percepção sensorial; sentidos, órgãos dos sentidos; percepção ou discernimento.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2669\" data-lsj-orig-id=\"n2669\" data-lsj-ordinal=\"2714\"><td class=\"greek\">αἰσθητήριον</td><td>LSJ</td><td>Órgão sensorial, sede dos sentidos; faculdades sensoriais.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2670\" data-lsj-orig-id=\"n2670\" data-lsj-ordinal=\"2715\"><td class=\"greek\">αἰσθητής</td><td>LSJ</td><td>Aquele que percebe, sujeito da percepção.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2671\" data-lsj-orig-id=\"n2671\" data-lsj-ordinal=\"2716\"><td class=\"greek\">αἰσθητικός</td><td>LSJ</td><td>Sensorial, sensível, perceptivo; perspicaz; consciente; perceptível em certos usos.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2672\" data-lsj-orig-id=\"n2672\" data-lsj-ordinal=\"2717\"><td class=\"greek\">αἰσθητός</td><td>LSJ</td><td>Sensível aos sentidos, perceptível; objeto da sensação, oposto a νοητός.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2673\" data-lsj-orig-id=\"n2673\" data-lsj-ordinal=\"2718\"><td class=\"greek\">αἴσθομαι</td><td>LSJ</td><td>Variante manuscrita de αἰσθάνομαι, perceber.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2674\" data-lsj-orig-id=\"n2674\" data-lsj-ordinal=\"2719\"><td class=\"greek\">ἀΐσθω</td><td>LSJ</td><td>Exalar o último suspiro, expirar; forma poética.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2675\" data-lsj-orig-id=\"n2675\" data-lsj-ordinal=\"2720\"><td class=\"greek\">αἰσιμία</td><td>LSJ</td><td>Distribuição justa, repartição apropriada.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2676\" data-lsj-orig-id=\"n2676\" data-lsj-ordinal=\"2721\"><td class=\"greek\">αἰσιμνάτας</td><td>LSJ</td><td>Remissão a αἰσυμνήτης.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2677\" data-lsj-orig-id=\"n2677\" data-lsj-ordinal=\"2722\"><td class=\"greek\">αἴσιμος</td><td>LSJ</td><td>Destinado pelos deuses, fatal; conforme ao destino, apropriado, justo, moderado.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2678\" data-lsj-orig-id=\"n2678\" data-lsj-ordinal=\"2723\"><td class=\"greek\">αἰσιμόω</td><td>LSJ</td><td>Gastar, despender; derivado para despesas em glosa.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2679\" data-lsj-orig-id=\"n2679\" data-lsj-ordinal=\"2724\"><td class=\"greek\">αἰσιομήτης</td><td>LSJ</td><td>Que oferece bons conselhos, de juízo correto.</td><td>LSJ</td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-source=\"LSJ\" data-target=\"entry-lsj-n2680\" data-lsj-orig-id=\"n2680\" data-lsj-ordinal=\"2725\"><td class=\"greek\">αἰσιόομαι</td><td>LSJ</td><td>Interpretar como bom presságio, julgar favorável.</td><td>LSJ</td></tr>";
